/* ---------------- CALENDLY PREVIEW ---------------- */
const CalendlyPreview = ({ onClick }) => {
  const today = new Date(); const days = [];
  for (let i = 0; i < 21; i++) { const d = new Date(today); d.setDate(d.getDate() + i); days.push(d); }
  return (
    <div className="card-soft p-6 lg:p-8">
      <div className="flex items-center justify-between mb-6">
        <div><Eyebrow>Private Consultation</Eyebrow><div className="font-display mt-2" style={{ fontSize: 22, fontWeight: 500 }}>30-minute session</div></div>
        <Calendar size={20} color={C.gold} strokeWidth={1.2} />
      </div>
      <div className="grid grid-cols-7 gap-1 mb-6">
        {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((d, i) => (<div key={i} className="text-center ui-eyebrow py-2" style={{ color: C.ink2, fontSize: 10 }}>{d}</div>))}
        {days.slice(0, 14).map((d, i) => { const wknd = d.getDay() === 0 || d.getDay() === 6; const avail = !wknd && i % 3 !== 0; return (<div key={i} className="aspect-square flex items-center justify-center text-sm" style={{ background: avail ? '#fff' : 'transparent', border: `1px solid ${avail ? C.hair : 'transparent'}`, color: avail ? C.ink : C.ink2, opacity: avail ? 1 : 0.4, fontFamily: 'Inter', fontWeight: 500 }}>{d.getDate()}</div>); })}
      </div>
      <div className="hairline border-t pt-6 space-y-2">
        <div className="ui-eyebrow" style={{ color: C.ink2 }}>Available time slots</div>
        <div className="flex flex-wrap gap-2 mt-3">{['9:00 AM', '10:30 AM', '1:00 PM', '2:30 PM', '4:00 PM'].map((t) => (<div key={t} className="px-3 py-1.5 text-xs" style={{ background: C.bg2, color: C.ink, fontFamily: 'Inter', fontWeight: 500 }}>{t}</div>))}</div>
      </div>
      <button onClick={onClick} className="lux-btn lux-btn-primary w-full justify-center mt-6">Open Booking <ArrowRight size={14} /></button>
      <p className="text-xs mt-3 text-center" style={{ color: C.ink2 }}>Powered by Calendly · Confidential</p>
    </div>
  );
};

/* ---------------- BUYER QUESTIONNAIRE ---------------- */
function BuyerQuestionnaire({ go, addToast }) {
  const [a, setA] = useState({ goal: '', budget: 'Select range', area: 'Select area', timeline: '', approval: '', name: '', email: '' });
  const [sending, setSending] = useState(false);
  const set = (k, v) => setA((p) => ({ ...p, [k]: v }));
  const handleField = (k) => (e) => set(k, e.target.value);
  const ready = a.goal && a.timeline && a.approval && a.budget !== 'Select range' && a.name && a.email;
  const submit = async () => {
    if (!ready) { addToast('Please complete the questionnaire'); return; }
    if (sending) return;
    setSending(true);
    const ok = await submitToFormspree({
      formId: FORMSPREE.buyerQuestionnaire,
      payload: {
        name: a.name,
        email: a.email,
        looking_for: a.goal,
        budget: a.budget,
        preferred_area: a.area,
        timeline: a.timeline,
        pre_approval: a.approval,
        _subject: `Buyer Questionnaire — ${a.name} (${a.budget}, ${a.timeline})`,
        _replyto: a.email,
      },
      mailtoSubject: `New Buyer Questionnaire — ${a.name}`,
      mailtoBody: `Name: ${a.name}\nEmail: ${a.email}\n\nLooking for: ${a.goal}\nBudget: ${a.budget}\nArea: ${a.area}\nTimeline: ${a.timeline}\nPre-approval: ${a.approval}`,
      addToast,
    });
    setSending(false);
    if (ok) { addToast('Thank you · Choose a time that suits you'); go('contact'); }
  };
  return (
    <div className="card-soft p-6 lg:p-10">
      <div className="flex items-center justify-between mb-8 flex-wrap gap-4">
        <Eyebrow>Tell Us What You're Seeking</Eyebrow>
        <div className="text-xs" style={{ color: C.ink2 }}>Takes under a minute · Confidential</div>
      </div>
      <div className="space-y-8">
        <div>
          <div className="ui-eyebrow mb-3" style={{ color: C.ink2 }}>What are you looking to buy?</div>
          <div className="flex flex-wrap gap-2">{['Primary Residence', 'Second Home', 'Investment', 'Not Sure Yet'].map((o) => (<ChoiceChip key={o} label={o} active={a.goal === o} onClick={() => set('goal', o)} />))}</div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <SelectField label="Target budget" value={a.budget} onChange={(v) => set('budget', v)} options={['Select range', 'Under $500k', '$500k – $1M', '$1M – $2M', '$2M – $5M', '$5M+']} />
          <SelectField label="Preferred area (South Florida)" value={a.area} onChange={(v) => set('area', v)} options={['Select area', 'Coral Gables', 'Pinecrest', 'Brickell', 'Coconut Grove', 'Key Biscayne', 'Other / Open']} />
        </div>
        <div>
          <div className="ui-eyebrow mb-3" style={{ color: C.ink2 }}>Your timeline</div>
          <div className="flex flex-wrap gap-2">{['ASAP', '1–3 months', '3–6 months', 'Just exploring'].map((o) => (<ChoiceChip key={o} label={o} active={a.timeline === o} onClick={() => set('timeline', o)} />))}</div>
        </div>
        <div>
          <div className="ui-eyebrow mb-3" style={{ color: C.ink2 }}>Are you pre-approved?</div>
          <div className="flex flex-wrap gap-2">{['Yes, pre-approved', 'Not yet — need a lender', 'Paying cash'].map((o) => (<ChoiceChip key={o} label={o} active={a.approval === o} onClick={() => set('approval', o)} />))}</div>
        </div>
        <div className="pt-4 hairline border-t">
          <div className="ui-eyebrow mb-5 mt-5" style={{ color: C.ink2 }}>So we can follow up</div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Field label="Full Name *"><input className="num-input" type="text" required value={a.name} onChange={handleField('name')} placeholder="Jane Smith" style={{ fontSize: 18 }} /></Field>
            <Field label="Email *"><input className="num-input" type="email" required value={a.email} onChange={handleField('email')} placeholder="jane@example.com" style={{ fontSize: 18 }} /></Field>
          </div>
        </div>
        <div className="pt-2 flex flex-col sm:flex-row sm:items-center gap-4">
          <button onClick={submit} disabled={sending} className="lux-btn lux-btn-primary justify-center" style={{ opacity: (ready && !sending) ? 1 : 0.55, cursor: sending ? 'wait' : 'pointer' }}>{sending ? 'Sending…' : <>Book a Call to Discuss <Calendar size={14} /></>}</button>
          <p className="text-xs" style={{ color: C.ink2 }}>We'll review your answers, then you'll choose a date &amp; time on Calendly.</p>
        </div>
      </div>
    </div>
  );
}

