/* ---------------- APP ROOT ---------------- */
export default function App() {
  useGlobalStyles();
  const [page, setPage] = useState('home');
  const [toasts, setToasts] = useState([]);
  const addToast = useCallback((msg) => {
    const id = Date.now();
    setToasts((t) => [...t, { id, msg }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3200);
  }, []);
  useEffect(() => { window.scrollTo({ top: 0, behavior: 'instant' }); }, [page]);
  const go = (p) => setPage(p);
  return (
    <div style={{ background: C.bg, color: C.ink, fontFamily: 'Inter, system-ui, sans-serif', minHeight: '100vh' }}>
      <Navigation page={page} go={go} />
      <div key={page} className="auto-fade-up">
        {page === 'home' && <HomePage go={go} />}
        {page === 'about' && <AboutPage go={go} />}
        {page === 'buyers' && <BuyersPage go={go} addToast={addToast} />}
        {page === 'sellers' && <SellersPage go={go} addToast={addToast} />}
        {page === 'agents' && <AgentEcosystemPage go={go} />}
        {page === 'usa' && <USACalculator go={go} addToast={addToast} />}
        {page === 'canada' && <CanadaCalculator go={go} addToast={addToast} />}
        {page === 'team' && <TeamCalculator go={go} addToast={addToast} />}
        {page === 'revshare' && <RevenueSharePage go={go} />}
        {page === 'contact' && <ContactPage addToast={addToast} />}
        {page === 'equal-housing' && <EqualHousingPage go={go} />}
        {page === 'privacy' && <PrivacyPage go={go} />}
      </div>
      <Footer go={go} />
      {toasts.map((t, idx) => (<div key={t.id} className="toast" style={{ bottom: `${24 + idx * 60}px` }}>{t.msg}</div>))}
    </div>
  );
}
